 public function list(int$u,array$q):array{$f=[];if(isset($q['status'])&&$q['status']!=='')$f['status']=$this->v->oneOf($q['status'],TaskStatus::all(),'status_invalid');if(isset($q['priority'])&&$q['priority']!=='')$f['priority']=$this->v->oneOf($q['priority'],['low','normal','high','urgent'],'priority_invalid');foreach(['project_id'=>'project_id_','session_id'=>'session_id_']as$in=>$db)if(isset($q[$in])&&$q[$in]!=='')$f[$db]=$this->v->positiveInt($q,$in);if(isset($q['q'])){$search=trim((string)$q['q']);if(mb_strlen($search)>200)throw new TaskValidationException('search_invalid');if($search!=='')$f['q']=$search;}$limit=isset($q['limit'])?(int)$q['limit']:25;$offset=isset($q['offset'])?(int)$q['offset']:0;if($limit<1||$limit>100||$offset<0)throw new TaskValidationException('pagination_invalid');$rows=$this->tasks->listOwned($u,$f,$limit,$offset);return['tasks'=>array_map(fn($r)=>$this->taskDto($r),$rows),'total'=>$this->tasks->countOwned($u,$f),'limit'=>$limit,'offset'=>$offset];}
