 public function addDependency(int$u,array$d):array{if(!$this->dependencyService)throw new RuntimeException('dependency_service_unavailable');$task=$this->v->publicId($d['public_id']??'');$required=$this->v->publicId($d['depends_on_public_id']??'');$this->dependencyService->add($u,$task,$required,(string)($d['condition']??'completed'));return['added'=>true];}
 public function removeDependency(int$u,array$d):array{if(!$this->dependencyService)throw new RuntimeException('dependency_service_unavailable');$this->dependencyService->remove($u,$this->v->publicId($d['public_id']??''),$this->v->publicId($d['depends_on_public_id']??''));return['removed'=>true];}
 public function retry(int$u,array$d):array{$t=$this->owned($u,$this->v->publicId($d['public_id']??''));return['task'=>$this->taskDto($this->orchestrator->retryTask((int)$t['id_'],$u,$this->v->lock($d)))];}
 private function owned(int$u,string$p):array{return$this->tasks->findOwnedByPublicId($p,$u)??throw new TaskNotFoundException('not_found');}
 private function stepKey(array$d):string{$k=trim((string)($d['step_key']??''));if(!preg_match('/^[a-z][a-z0-9_-]{0,63}$/D',$k))throw new TaskValidationException('step_key_invalid');return$k;}
 private function decideTool(int$u,array$d,bool$approved):array{if(!$this->toolApproval)throw new RuntimeException('tool_approval_service_unavailable');$fingerprint=(string)($d['fingerprint']??'');if(preg_match('/^[a-f0-9]{64}$/D',$fingerprint)!==1)throw new TaskValidationException('tool_approval_fingerprint_invalid');return$this->toolApproval->decide($u,$this->v->publicId($d['public_id']??''),$this->stepKey($d),$this->v->lock($d),$fingerprint,$approved);}
 private function taskDto(array$r):array{$dto=['public_id'=>$r['public_id'],'project_id'=>$r['project_id_']===null?null:(int)$r['project_id_'],'session_id'=>(int)$r['session_id_'],'origin_message_id'=>$r['origin_message_id_']===null?null:(int)$r['origin_message_id_'],'result_message_id'=>$r['result_message_id_']===null?null:(int)$r['result_message_id_'],'origin_type'=>$r['origin_type'],'title'=>$r['title'],'objective'=>$r['objective'],'status'=>$r['status'],'priority'=>$r['priority'],'progress_percent'=>(int)$r['progress_percent'],'max_attempts'=>(int)$r['max_attempts'],'attempt_count'=>(int)$r['attempt_count'],'lock_version'=>(int)$r['lock_version'],'scheduled_at'=>$r['scheduled_at'],'started_at'=>$r['started_at'],'due_at'=>$r['due_at'],'completed_at'=>$r['completed_at'],'cancel_requested_at'=>$r['cancel_requested_at'],'cancelled_at'=>$r['cancelled_at'],'result_summary'=>$r['result_summary'],'error_code'=>$r['error_code'],'error_message'=>$r['error_message'],'created_at'=>$r['created_at'],'updated_at'=>$r['updated_at']];$dto['error_message']=$this->safeError($dto['error_message']);$dto['result_summary']=$this->safeSummary($dto['result_summary']);if(array_key_exists('current_step_key',$r))$dto['current_step']=$r['current_step_key']===null?null:['step_key'=>(string)$r['current_step_key'],'title'=>(string)$r['current_step_title'],'step_type'=>(string)$r['current_step_type'],'status'=>(string)$r['current_step_status'],'agent_key'=>$r['current_step_agent_key']===null?null:(string)$r['current_step_agent_key'],'model_id'=>$r['current_step_model_id']===null?null:(string)$r['current_step_model_id'],'wait_until'=>$this->waitUntil((string)$r['current_step_type'],$r['current_step_checkpoint_json']??null)];return$dto;}
