 private function safeError(mixed$value):?string{if(!is_string($value)||trim($value)==='')return null;$text=preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u',' ',trim($value))??'';$text=preg_replace('/\b(password|token|secret|authorization|api[_-]?key)\s*[:=]\s*[^\s,;]+/iu','$1=[oculto]',$text)??'';if(preg_match('/\b(?:SELECT|INSERT|UPDATE|DELETE)\b.+\b(?:FROM|INTO|SET)\b/iu',$text))return'Detalle técnico oculto.';$line=trim(strtok($text,"\n")?:'');return mb_strlen($line)>300?mb_substr($line,0,297).'…':$line;}
